    </View>
  ))}
</ScrollView>

<SectionProgress
  scroll={sections.scroll}
  value={sections.active}
  onValueChange={sections.scrollTo}
>
  {SECTIONS.map((section) => (
    <SectionProgress.Item key={section.id} value={section.id}>
      {section.label}
    </SectionProgress.Item>
  ))}
</SectionProgress>

